import csv
TS = "8bbaca4c-ba89-5d74-a9f7-d452d1eeef2e"
SP = "9f8698d1-77a4-5b0d-90ee-d5b6fe3963d8"
from collections import defaultdict
data = {TS: defaultdict(float), SP: defaultdict(float)}
with open(VALUES_CSV) as f:
    r = csv.reader(f)
    header = next(r)
    for row in r:
        ts, t, v = row[0], row[1], float(row[2])
        if ts in data:
            data[ts][t] = v

def mean_dev(date):
    devs = []
    for t, temp in data[TS].items():
        if not t.startswith(date):
            continue
        h = int(t[11:13])
        if not (8 <= h <= 18):
            continue
        if t in data[SP] and t in data[TS]:
            devs.append(temp - data[SP][t])
    return sum(devs)/len(devs), len(devs)

m1, n1 = mean_dev("2018-01-17")
m2, n2 = mean_dev("2018-10-26")
print(m1, n1, m2, n2)
print("increase" if m2 > m1 else "decrease")
